        // Pulled out of InitializeComponent so the visual Designer can
        // still open this file (it can't parse local functions).
        private void BuildBarRow(Label label, ProgressBar bar, Label count, string text, int y)
        {
            label.Text = text;
            label.ForeColor = Color.FromArgb(138, 148, 168);
            label.Location = new Point(480, y);
            label.Size = new Size(45, 20);

            bar.Location = new Point(530, y + 2);
            bar.Size = new Size(150, 12);
            bar.Maximum = 100;

            count.ForeColor = Color.FromArgb(245, 247, 250);
            count.Location = new Point(690, y);
            count.AutoSize = true;

            this.Controls.Add(label);
            this.Controls.Add(bar);
            this.Controls.Add(count);
        }

